def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if history[0][1] == 'D':
        return 'D'

    opp_def = 0
    own_def = 0
    for h in history:
        if h[1] == 'D':
            opp_def += 1
        if h[0] == 'D':
            own_def += 1

    if opp_def == 0:
        if own_def >= 5:
            return 'D'
        if n in (10, 16, 22, 28, 34):
            return 'D'
        return 'C'

    last_my, last_opp = history[-1]
    if last_opp == 'D':
        if opp_def <= n // 4 and rng.random() < 0.2:
            return 'C'
        return 'D'
    if opp_def > own_def and n >= 50:
        return 'D'
    if opp_def <= n // 4:
        return 'C'
    if opp_def > n // 2:
        if rng.random() < 0.7:
            return 'D'
        return 'C'
    return 'C'
